// Generated by GitHub Copilot
/**
 * generate-snapshot.mjs — Génère un catalogue multi-ETF embarqué (data-snapshot.js)
 *
 * Node n'est PAS soumis au CORS : ce script récupère les vraies données Yahoo
 * Finance pour les ETFs réels et génère des données seedées cohérentes pour les
 * ETF-Test. Le résultat est écrit dans data-snapshot.js sous forme d'un catalogue
 * window.ETF_CATALOG, et window.CW8_SNAPSHOT est conservé pour la rétro-compat.
 *
 * Usage: node generate-snapshot.mjs
 */

const RANGE = '5y';
const INTERVAL = '1d';

// ETFs réels (données Yahoo Finance)
const REAL_ETFS = [
    { id: 'CW8.PA', name: 'Amundi MSCI World (CW8)', isin: 'LU1681043599', ticker: 'CW8.PA' },
    { id: 'EWLD.PA', name: 'Amundi MSCI World Dist', isin: 'LU2655993207', ticker: 'EWLD.PA' },
    { id: 'ETSZ.DE', name: 'BNPP STOXX Europe 600', isin: 'FR0011550193', ticker: 'ETSZ.DE' },
    { id: 'PAEEM.PA', name: 'Amundi PEA MSCI Emerging Markets', isin: 'FR0013412020', ticker: 'PAEEM.PA' },
    { id: 'PSP5.PA', name: 'Amundi PEA S&P 500', isin: 'FR0011871128', ticker: 'PSP5.PA' }
];

// ETFs seedés (random cohérent). start = prix de départ, drift/vol annualisés.
const SEED_ETFS = [
    { id: 'ETF-Test1', name: 'ETF-Test1', start: 100, drift: 0.08, vol: 0.15 },
    { id: 'ETF-Test2', name: 'ETF-Test2', start: 50, drift: 0.05, vol: 0.12 },
    { id: 'ETF-Test3', name: 'ETF-Test3', start: 200, drift: 0.12, vol: 0.22 },
    { id: 'ETF-Test4', name: 'ETF-Test4', start: 80, drift: 0.03, vol: 0.10 },
    { id: 'ETF-Test5', name: 'ETF-Test5', start: 150, drift: 0.10, vol: 0.18 },
    { id: 'ETF-Test6', name: 'ETF-Test6', start: 120, drift: 0.06, vol: 0.14 }
];

const round2 = (v) => (v === null || v === undefined || Number.isNaN(v) ? null : Math.round(v * 100) / 100);

/**
 * Récupère les données OHLCV réelles d'un ticker Yahoo.
 */
async function fetchReal(ticker) {
    const url = `https://query1.finance.yahoo.com/v8/finance/chart/${ticker}` +
        `?interval=${INTERVAL}&range=${RANGE}`;
    const res = await fetch(url, { headers: { Accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status} pour ${ticker}`);

    const json = await res.json();
    const result = json?.chart?.result?.[0];
    if (!result) throw new Error(`Réponse Yahoo inattendue pour ${ticker}`);

    const timestamps = result.timestamp || [];
    const q = result.indicators.quote[0];

    return timestamps.map((ts, i) => ({
        date: new Date(ts * 1000).toISOString().split('T')[0],
        open: round2(q.open[i]),
        high: round2(q.high[i]),
        low: round2(q.low[i]),
        close: round2(q.close[i]),
        volume: q.volume[i] ?? 0
    })).filter((d) => d.close !== null);
}

/** Générateur normal (Box-Muller). */
function randn() {
    let u = 0;
    let v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

/**
 * Génère une série OHLCV seedée (marche géométrique) sur un calendrier de dates.
 */
function generateSeed(dates, { start, drift, vol }) {
    const dailyDrift = drift / 252;
    const dailyVol = vol / Math.sqrt(252);
    let close = start;
    const rows = [];
    for (const date of dates) {
        const prevClose = close;
        const ret = dailyDrift + dailyVol * randn();
        close = prevClose * Math.exp(ret);
        const open = prevClose * (1 + (Math.random() - 0.5) * 0.004);
        const high = Math.max(open, close) * (1 + Math.random() * 0.006);
        const low = Math.min(open, close) * (1 - Math.random() * 0.006);
        const volume = Math.floor(Math.random() * 900000) + 100000;
        rows.push({
            date,
            open: round2(open),
            high: round2(high),
            low: round2(low),
            close: round2(close),
            volume
        });
    }
    return rows;
}

async function main() {
    const catalog = [];

    // 1) ETFs réels
    for (const etf of REAL_ETFS) {
        try {
            process.stdout.write(`Récupération ${etf.ticker}... `);
            const data = await fetchReal(etf.ticker);
            catalog.push({ ...etf, source: 'real', data });
            console.log(`OK (${data.length} pts, ${data[0].date} -> ${data[data.length - 1].date})`);
        } catch (err) {
            console.log(`ECHEC: ${err.message}`);
        }
    }

    // Calendrier de référence = dates de CW8.PA (le plus long historique réel)
    const cw8 = catalog.find((e) => e.id === 'CW8.PA');
    if (!cw8) throw new Error('CW8.PA indisponible : impossible de définir le calendrier');
    const dates = cw8.data.map((d) => d.date);

    // 2) ETFs seedés (sur le calendrier CW8)
    for (const seed of SEED_ETFS) {
        const data = generateSeed(dates, seed);
        catalog.push({
            id: seed.id,
            name: seed.name,
            isin: '',
            ticker: '',
            source: 'seed',
            data
        });
        console.log(`Seed ${seed.id}: ${data.length} pts (${data[0].close} -> ${data[data.length - 1].close})`);
    }

    const generatedAt = new Date().toISOString();
    const header = `// Catalogue multi-ETF — généré le ${generatedAt}\n` +
        `// Réels: Yahoo Finance (${RANGE}, ${INTERVAL}). Seedés: marche géométrique.\n` +
        `// Régénérer: node generate-snapshot.mjs\n`;
    const body =
        `window.ETF_CATALOG = ${JSON.stringify(catalog)};\n` +
        `window.CW8_SNAPSHOT = ${JSON.stringify(cw8.data)};\n` +
        `window.CW8_SNAPSHOT_META = { generatedAt: "${generatedAt}", ticker: "CW8.PA", points: ${cw8.data.length} };\n`;

    const { writeFileSync } = await import('node:fs');
    writeFileSync('data-snapshot.js', header + body, 'utf8');

    console.log(`\nOK: catalogue de ${catalog.length} ETFs écrit dans data-snapshot.js`);
}

main().catch((err) => {
    console.error('Échec:', err.message);
    process.exit(1);
});
